155→func TestChunkTranscript_LargeContent(t *testing.T) {
156→	t.Parallel()
157→	ag := &FactoryAIDroidAgent{}
158→
159→	// Build multi-line JSONL that exceeds a small maxSize
160→	var lines []string
161→	for i := range 50 {
162→		lines = append(lines, fmt.Sprintf(`{"role":"user","content":"message %d %s"}`, i, strings.Repeat("x", 200)))
163→	}
164→	content := []byte(strings.Join(lines, "\n"))
165→
166→	maxSize := 2000
167→	chunks, err := ag.ChunkTranscript(content, maxSize)
168→	if err != nil {
169→		t.Fatalf("ChunkTranscript() error = %v", err)
170→	}
171→	if len(chunks) < 2 {
172→		t.Errorf("Expected at least 2 chunks for large content, got %d", len(chunks))
173→	}
174→
175→	// Verify each chunk is valid JSONL (each line is valid JSON)
176→	for i, chunk := range chunks {
177→		chunkLines := strings.Split(string(chunk), "\n")
178→		for j, line := range chunkLines {
179→			if line == "" {
180→				continue
181→			}
182→			if line[0] != '{' {
183→				t.Errorf("Chunk %d, line %d doesn't look like JSON: %q", i, j, line[:min(len(line), 40)])
184→			}
185→		}
186→	}
187→}
