  1→// Package factoryaidroid implements the Agent interface for Factory AI Droid.
  2→package factoryaidroid
  3→
  4→import (
  5→	"errors"
  6→	"fmt"
  7→	"io"
  8→	"os"
  9→	"path/filepath"
 10→	"regexp"
 11→
 12→	"github.com/entireio/cli/cmd/entire/cli/agent"
 13→	"github.com/entireio/cli/cmd/entire/cli/paths"
 14→)
 15→
 16→// nonAlphanumericRegex matches any non-alphanumeric character for path sanitization.
 17→// Same pattern as claudecode.SanitizePathForClaude — duplicated to avoid cross-package dependency.
 18→var nonAlphanumericRegex = regexp.MustCompile(`[^a-zA-Z0-9]`)
 19→
 20→func sanitizeRepoPath(path string) string {
 21→	return nonAlphanumericRegex.ReplaceAllString(path, "-")
 22→}
 23→
 24→//nolint:gochecknoinits // Agent self-registration is the intended pattern
 25→func init() {
 26→	agent.Register(agent.AgentNameFactoryAIDroid, NewFactoryAIDroidAgent)
 27→}
 28→
 29→// FactoryAIDroidAgent implements the agent.Agent interface for Factory AI Droid.
 30→//
 31→//nolint:revive // FactoryAIDroidAgent is clearer than Agent in this context
 32→type FactoryAIDroidAgent struct{}
 33→
 34→// NewFactoryAIDroidAgent creates a new Factory AI Droid agent instance.
 35→func NewFactoryAIDroidAgent() agent.Agent {
 36→	return &FactoryAIDroidAgent{}
 37→}
 38→
 39→// Name returns the agent registry key.
 40→func (f *FactoryAIDroidAgent) Name() agent.AgentName { return agent.AgentNameFactoryAIDroid }
 41→
 42→// Type returns the agent type identifier.
 43→func (f *FactoryAIDroidAgent) Type() agent.AgentType { return agent.AgentTypeFactoryAIDroid }
 44→
 45→// Description returns a human-readable description.
 46→func (f *FactoryAIDroidAgent) Description() string {
 47→	return "Factory AI Droid - agent-native development platform"
 48→}
 49→
 50→// IsPreview returns true as Factory AI Droid integration is in preview.
 51→func (f *FactoryAIDroidAgent) IsPreview() bool { return true }
 52→
 53→// ProtectedDirs returns directories that Factory AI Droid uses for config/state.
 54→func (f *FactoryAIDroidAgent) ProtectedDirs() []string { return []string{".factory"} }
 55→
 56→// DetectPresence checks if Factory AI Droid is configured in the repository.
 57→func (f *FactoryAIDroidAgent) DetectPresence() (bool, error) {
 58→	repoRoot, err := paths.RepoRoot()
 59→	if err != nil {
 60→		repoRoot = "."
 61→	}
 62→	if _, err := os.Stat(filepath.Join(repoRoot, ".factory")); err == nil {
 63→		return true, nil
 64→	}
 65→	return false, nil
 66→}
 67→
 68→// ReadTranscript reads the raw JSONL transcript bytes for a session.
 69→func (f *FactoryAIDroidAgent) ReadTranscript(sessionRef string) ([]byte, error) {
 70→	data, err := os.ReadFile(sessionRef) //nolint:gosec // Path comes from agent hook input
 71→	if err != nil {
 72→		return nil, fmt.Errorf("failed to read transcript: %w", err)
 73→	}
 74→	return data, nil
 75→}
 76→
 77→// ChunkTranscript splits a JSONL transcript at line boundaries.
 78→func (f *FactoryAIDroidAgent) ChunkTranscript(content []byte, maxSize int) ([][]byte, error) {
 79→	chunks, err := agent.ChunkJSONL(content, maxSize)
 80→	if err != nil {
 81→		return nil, fmt.Errorf("failed to chunk transcript: %w", err)
 82→	}
 83→	return chunks, nil
 84→}
 85→
 86→// ReassembleTranscript concatenates JSONL chunks with newlines.
 87→func (f *FactoryAIDroidAgent) ReassembleTranscript(chunks [][]byte) ([]byte, error) {
 88→	return agent.ReassembleJSONL(chunks), nil
 89→}
 90→
 91→// GetHookConfigPath returns the path to Factory AI Droid's hook config file.
 92→func (f *FactoryAIDroidAgent) GetHookConfigPath() string { return ".factory/settings.json" }
 93→
 94→// SupportsHooks returns true as Factory AI Droid supports lifecycle hooks.
 95→func (f *FactoryAIDroidAgent) SupportsHooks() bool { return true }
 96→
 97→// ParseHookInput parses Factory AI Droid hook input from stdin.
 98→func (f *FactoryAIDroidAgent) ParseHookInput(_ agent.HookType, r io.Reader) (*agent.HookInput, error) {
 99→	raw, err := agent.ReadAndParseHookInput[sessionInfoRaw](r)
100→	if err != nil {
101→		return nil, err
102→	}
103→	return &agent.HookInput{
104→		SessionID:  raw.SessionID,
105→		SessionRef: raw.TranscriptPath,
106→	}, nil
107→}
108→
109→// GetSessionID extracts the session ID from hook input.
110→func (f *FactoryAIDroidAgent) GetSessionID(input *agent.HookInput) string { return input.SessionID }
111→
112→// GetSessionDir returns the directory where Factory AI Droid stores session transcripts.
113→// Path: ~/.factory/sessions/<sanitized-repo-path>/
114→func (f *FactoryAIDroidAgent) GetSessionDir(repoPath string) (string, error) {
115→	if override := os.Getenv("ENTIRE_TEST_DROID_PROJECT_DIR"); override != "" {
116→		return override, nil
117→	}
118→	homeDir, err := os.UserHomeDir()
119→	if err != nil {
120→		return "", fmt.Errorf("failed to get home directory: %w", err)
121→	}
122→	projectDir := sanitizeRepoPath(repoPath)
123→	return filepath.Join(homeDir, ".factory", "sessions", projectDir), nil
124→}
125→
126→// ResolveSessionFile returns the path to a Factory AI Droid session file.
127→func (f *FactoryAIDroidAgent) ResolveSessionFile(sessionDir, agentSessionID string) string {
128→	return filepath.Join(sessionDir, agentSessionID+".jsonl")
129→}
130→
131→// ReadSession is not implemented for Factory AI Droid.
132→func (f *FactoryAIDroidAgent) ReadSession(_ *agent.HookInput) (*agent.AgentSession, error) {
133→	return nil, errors.New("not implemented")
134→}
135→
136→// WriteSession is not implemented for Factory AI Droid.
137→func (f *FactoryAIDroidAgent) WriteSession(_ *agent.AgentSession) error {
138→	return errors.New("not implemented")
139→}
140→
141→// FormatResumeCommand returns the command to resume a Factory AI Droid session.
142→func (f *FactoryAIDroidAgent) FormatResumeCommand(sessionID string) string {
143→	return "droid --session-id " + sessionID
144→}
