274→					"output_tokens":               1, // First streaming chunk
275→				},
276→			}),
277→		},
278→		{
279→			Type: "assistant",
280→			UUID: "asst-2",
281→			Message: mustMarshal(t, map[string]interface{}{
282→				"id": "msg_001", // Same message ID
