522→func TestCalculateTotalTokenUsageFromTranscript_PerCheckpoint(t *testing.T) {
523→	t.Parallel()
524→
525→	tmpDir := t.TempDir()
526→	transcriptPath := tmpDir + "/transcript.jsonl"
527→
528→	// Build transcript with 3 turns:
529→	// Turn 1: user + assistant (100 input, 50 output)
530→	// Turn 2: user + assistant (200 input, 100 output)
531→	// Turn 3: user + assistant (300 input, 150 output)
532→	//
533→	// Lines:
534→	// 0: user message 1
535→	// 1: assistant response 1 (100/50 tokens)
536→	// 2: user message 2
537→	// 3: assistant response 2 (200/100 tokens)
538→	// 4: user message 3
539→	// 5: assistant response 3 (300/150 tokens)
540→
541→	// Droid format: outer type is always "message", role is inside the inner message
542→	transcriptContent := []byte(
543→		`{"type":"message","id":"u1","message":{"role":"user","content":"first prompt"}}` + "\n" +
544→			`{"type":"message","id":"a1","message":{"role":"assistant","id":"m1","usage":{"input_tokens":100,"output_tokens":50}}}` + "\n" +
545→			`{"type":"message","id":"u2","message":{"role":"user","content":"second prompt"}}` + "\n" +
546→			`{"type":"message","id":"a2","message":{"role":"assistant","id":"m2","usage":{"input_tokens":200,"output_tokens":100}}}` + "\n" +
547→			`{"type":"message","id":"u3","message":{"role":"user","content":"third prompt"}}` + "\n" +
548→			`{"type":"message","id":"a3","message":{"role":"assistant","id":"m3","usage":{"input_tokens":300,"output_tokens":150}}}` + "\n",
549→	)
550→	if err := os.WriteFile(transcriptPath, transcriptContent, 0o600); err != nil {
551→		t.Fatalf("failed to write transcript: %v", err)
552→	}
553→
554→	// Test 1: From line 0 - all 3 turns = 600 input, 300 output
555→	usage1, err := CalculateTotalTokenUsageFromTranscript(transcriptPath, 0, "")
556→	if err != nil {
557→		t.Fatalf("CalculateTotalTokenUsageFromTranscript(0) error: %v", err)
558→	}
559→	if usage1.InputTokens != 600 || usage1.OutputTokens != 300 {
560→		t.Errorf("From line 0: got input=%d output=%d, want input=600 output=300",
561→			usage1.InputTokens, usage1.OutputTokens)
562→	}
563→	if usage1.APICallCount != 3 {
564→		t.Errorf("From line 0: got APICallCount=%d, want 3", usage1.APICallCount)
565→	}
566→
567→	// Test 2: From line 2 (after turn 1) - turns 2+3 only = 500 input, 250 output
568→	usage2, err := CalculateTotalTokenUsageFromTranscript(transcriptPath, 2, "")
569→	if err != nil {
570→		t.Fatalf("CalculateTotalTokenUsageFromTranscript(2) error: %v", err)
571→	}
572→	if usage2.InputTokens != 500 || usage2.OutputTokens != 250 {
573→		t.Errorf("From line 2: got input=%d output=%d, want input=500 output=250",
574→			usage2.InputTokens, usage2.OutputTokens)
575→	}
576→	if usage2.APICallCount != 2 {
577→		t.Errorf("From line 2: got APICallCount=%d, want 2", usage2.APICallCount)
578→	}
579→
580→	// Test 3: From line 4 (after turns 1+2) - turn 3 only = 300 input, 150 output
581→	usage3, err := CalculateTotalTokenUsageFromTranscript(transcriptPath, 4, "")
582→	if err != nil {
583→		t.Fatalf("CalculateTotalTokenUsageFromTranscript(4) error: %v", err)
584→	}
585→	if usage3.InputTokens != 300 || usage3.OutputTokens != 150 {
586→		t.Errorf("From line 4: got input=%d output=%d, want input=300 output=150",
587→			usage3.InputTokens, usage3.OutputTokens)
588→	}
589→	if usage3.APICallCount != 1 {
590→		t.Errorf("From line 4: got APICallCount=%d, want 1", usage3.APICallCount)
591→	}
592→}
