248→// parseHookType parses a specific hook type from rawHooks into the target slice.
249→// Silently ignores parse errors (leaves target unchanged).
250→func parseHookType(rawHooks map[string]json.RawMessage, hookType string, target *[]FactoryHookMatcher) {
251→	if data, ok := rawHooks[hookType]; ok {
252→		//nolint:errcheck,gosec // Intentionally ignoring parse errors - leave target as nil/empty
253→		json.Unmarshal(data, target)
254→	}
255→}
256→
257→// marshalHookType marshals a hook type back to rawHooks.
258→// If the slice is empty, removes the key from rawHooks.
259→func marshalHookType(rawHooks map[string]json.RawMessage, hookType string, matchers []FactoryHookMatcher) {
260→	if len(matchers) == 0 {
261→		delete(rawHooks, hookType)
262→		return
263→	}
264→	data, err := json.Marshal(matchers)
265→	if err != nil {
266→		return // Silently ignore marshal errors (shouldn't happen)
267→	}
268→	rawHooks[hookType] = data
269→}
