395→	// Use repo root to find .factory directory when run from a subdirectory
396→	repoRoot, err := paths.RepoRoot()
397→	if err != nil {
398→		repoRoot = "." // Fallback to CWD if not in a git repo
399→	}
400→	settingsPath := filepath.Join(repoRoot, ".factory", FactorySettingsFileName)
401→	data, err := os.ReadFile(settingsPath) //nolint:gosec // path is constructed from repo root + fixed path
402→	if err != nil {
403→		return false
404→	}
405→
406→	var settings FactorySettings
407→	if err := json.Unmarshal(data, &settings); err != nil {
408→		return false
409→	}
410→
411→	// Check for at least one of our hooks (new or old format)
412→	return hookCommandExists(settings.Hooks.Stop, "entire hooks factoryai-droid stop") ||
413→		hookCommandExists(settings.Hooks.Stop, "go run ${FACTORY_PROJECT_DIR}/cmd/entire/main.go hooks factoryai-droid stop")
