428→// Helper functions for hook management
429→
430→func hookCommandExists(matchers []FactoryHookMatcher, command string) bool {
431→	for _, matcher := range matchers {
432→		for _, hook := range matcher.Hooks {
433→			if hook.Command == command {
434→				return true
435→			}
436→		}
437→	}
438→	return false
439→}
440→
441→func hookCommandExistsWithMatcher(matchers []FactoryHookMatcher, matcherName, command string) bool {
442→	for _, matcher := range matchers {
443→		if matcher.Matcher == matcherName {
444→			for _, hook := range matcher.Hooks {
445→				if hook.Command == command {
446→					return true
447→				}
448→			}
449→		}
450→	}
451→	return false
452→}
453→
454→func addHookToMatcher(matchers []FactoryHookMatcher, matcherName, command string) []FactoryHookMatcher {
455→	entry := FactoryHookEntry{
456→		Type:    "command",
457→		Command: command,
458→	}
459→
460→	// If no matcher name, add to a matcher with empty string
461→	if matcherName == "" {
462→		for i, matcher := range matchers {
463→			if matcher.Matcher == "" {
464→				matchers[i].Hooks = append(matchers[i].Hooks, entry)
465→				return matchers
466→			}
467→		}
468→		return append(matchers, FactoryHookMatcher{
469→			Matcher: "",
470→			Hooks:   []FactoryHookEntry{entry},
471→		})
472→	}
473→
474→	// Find or create matcher with the given name
475→	for i, matcher := range matchers {
476→		if matcher.Matcher == matcherName {
477→			matchers[i].Hooks = append(matchers[i].Hooks, entry)
478→			return matchers
479→		}
480→	}
481→
482→	return append(matchers, FactoryHookMatcher{
483→		Matcher: matcherName,
484→		Hooks:   []FactoryHookEntry{entry},
485→	})
486→}
487→
488→// isEntireHook checks if a command is an Entire hook (old or new format)
489→func isEntireHook(command string) bool {
490→	for _, prefix := range entireHookPrefixes {
491→		if strings.HasPrefix(command, prefix) {
492→			return true
493→		}
494→	}
495→	return false
496→}
497→
498→// removeEntireHooks removes all Entire hooks from a list of matchers (for simple hooks like Stop)
499→func removeEntireHooks(matchers []FactoryHookMatcher) []FactoryHookMatcher {
500→	result := make([]FactoryHookMatcher, 0, len(matchers))
501→	for _, matcher := range matchers {
502→		filteredHooks := make([]FactoryHookEntry, 0, len(matcher.Hooks))
503→		for _, hook := range matcher.Hooks {
504→			if !isEntireHook(hook.Command) {
505→				filteredHooks = append(filteredHooks, hook)
506→			}
507→		}
508→		// Only keep the matcher if it has hooks remaining
509→		if len(filteredHooks) > 0 {
510→			matcher.Hooks = filteredHooks
511→			result = append(result, matcher)
512→		}
513→	}
514→	return result
515→}
516→
517→// removeEntireHooksFromMatchers removes Entire hooks from tool-use matchers (PreToolUse, PostToolUse)
518→// This handles the nested structure where hooks are grouped by tool matcher (e.g., "Task")
519→func removeEntireHooksFromMatchers(matchers []FactoryHookMatcher) []FactoryHookMatcher {
520→	// Same logic as removeEntireHooks - both work on the same structure
521→	return removeEntireHooks(matchers)
522→}
