 13→func TestInstallHooks_FreshInstall(t *testing.T) {
 14→	tempDir := t.TempDir()
 15→	t.Chdir(tempDir)
 16→
 17→	agent := &FactoryAIDroidAgent{}
 18→	count, err := agent.InstallHooks(false, false)
 19→	if err != nil {
 20→		t.Fatalf("InstallHooks() error = %v", err)
 21→	}
 22→
 23→	// 7 hooks: SessionStart, SessionEnd, Stop, UserPromptSubmit, PreToolUse[Task], PostToolUse[Task], PreCompact
 24→	if count != 7 {
 25→		t.Errorf("InstallHooks() count = %d, want 7", count)
 26→	}
 27→
 28→	// Verify settings.json was created with hooks
 29→	settings := readFactorySettings(t, tempDir)
 30→
 31→	if len(settings.Hooks.SessionStart) != 1 {
 32→		t.Errorf("SessionStart hooks = %d, want 1", len(settings.Hooks.SessionStart))
 33→	}
 34→	if len(settings.Hooks.SessionEnd) != 1 {
 35→		t.Errorf("SessionEnd hooks = %d, want 1", len(settings.Hooks.SessionEnd))
 36→	}
 37→	if len(settings.Hooks.Stop) != 1 {
 38→		t.Errorf("Stop hooks = %d, want 1", len(settings.Hooks.Stop))
 39→	}
 40→	if len(settings.Hooks.UserPromptSubmit) != 1 {
 41→		t.Errorf("UserPromptSubmit hooks = %d, want 1", len(settings.Hooks.UserPromptSubmit))
 42→	}
 43→	if len(settings.Hooks.PreToolUse) != 1 {
 44→		t.Errorf("PreToolUse hooks = %d, want 1", len(settings.Hooks.PreToolUse))
 45→	}
 46→	if len(settings.Hooks.PostToolUse) != 1 {
 47→		t.Errorf("PostToolUse hooks = %d, want 1", len(settings.Hooks.PostToolUse))
 48→	}
 49→	if len(settings.Hooks.PreCompact) != 1 {
 50→		t.Errorf("PreCompact hooks = %d, want 1", len(settings.Hooks.PreCompact))
 51→	}
 52→
 53→	// Verify hook commands
 54→	assertFactoryHookExists(t, settings.Hooks.SessionStart, "", "entire hooks factoryai-droid session-start", "SessionStart")
 55→	assertFactoryHookExists(t, settings.Hooks.SessionEnd, "", "entire hooks factoryai-droid session-end", "SessionEnd")
 56→	assertFactoryHookExists(t, settings.Hooks.Stop, "", "entire hooks factoryai-droid stop", "Stop")
 57→	assertFactoryHookExists(t, settings.Hooks.UserPromptSubmit, "", "entire hooks factoryai-droid user-prompt-submit", "UserPromptSubmit")
 58→	assertFactoryHookExists(t, settings.Hooks.PreToolUse, "Task", "entire hooks factoryai-droid pre-tool-use", "PreToolUse[Task]")
 59→	assertFactoryHookExists(t, settings.Hooks.PostToolUse, "Task", "entire hooks factoryai-droid post-tool-use", "PostToolUse[Task]")
 60→	assertFactoryHookExists(t, settings.Hooks.PreCompact, "", "entire hooks factoryai-droid pre-compact", "PreCompact")
 61→
 62→	// Verify AreHooksInstalled returns true
 63→	if !agent.AreHooksInstalled() {
 64→		t.Error("AreHooksInstalled() should return true after install")
 65→	}
 66→}
